#!/usr/bin/env bash
set -euo pipefail
cat > evidence-poster.html <<'HTML'
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Make evidence legible.</title><style>
:root{color-scheme:dark;font-family:ui-sans-serif,system-ui;background:#111;color:#f5f1e8}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#241f45}.poster{width:min(900px,calc(100vw - 34px));min-height:620px;padding:clamp(26px,6vw,72px);position:relative;overflow:hidden;background:#f4e8c8;color:#1e1b30;border-radius:20px;box-shadow:18px 20px 0 #b5a9ee}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.2em}.poster h1{max-width:650px;margin:80px 0 18px;font-size:clamp(48px,10vw,110px);line-height:.86;letter-spacing:-.08em}.lede{max-width:400px;font-size:18px;line-height:1.4}.stat{position:absolute;right:8%;top:13%;font-size:clamp(72px,13vw,150px);font-weight:900;line-height:.8;color:#6f58e8}.principles{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:80px}.principle{padding-top:12px;border-top:2px solid #1e1b30;font-weight:700}.principle small{display:block;margin-top:6px;font-weight:400;color:#655f72}.orb{position:absolute;right:-80px;bottom:-110px;width:300px;height:300px;border-radius:50%;background:#da685e;mix-blend-mode:multiply}@media(max-width:620px){.poster h1{margin-top:54px}.stat{position:static;margin-top:48px}.principles{grid-template-columns:1fr;margin-top:54px}.orb{opacity:.45}}
</style></head><body><main class="poster"><div class="eyebrow">OpenEval / evaluation craft</div><h1>Make evidence legible.</h1><p class="lede">A benchmark is a conversation with reality: show the work, name the uncertainty, and make the next decision easier.</p><div class="stat" aria-label="eighty seven percent">87%</div><section class="principles" aria-label="Principles"><div class="principle">Trace every turn<small>Keep the path, not just the answer.</small></div><div class="principle">Compare honestly<small>Separate speed, cost, and quality.</small></div><div class="principle">Keep humans in the loop<small>Make judgment visible where it matters.</small></div></section><div class="orb" aria-hidden="true"></div></main></body></html>
HTML
